2	import type React from "react";
3	
4	type BlobVariant = 'hero' | 'soft' | 'cta';
5	
6	interface BlobConfig {
7	  cx: string;
8	  cy: string;
9	  size: number;
10	  color: string;
11	  opacity: number;
12	}
13	
14	interface MangomintBlobsProps {
15	  variant?: BlobVariant;
16	}
17	
18	const blobVariants: Record<BlobVariant, BlobConfig[]> = {
19	  hero: [
20	    { cx: '85%', cy: '15%', size: 700, color: BRAND.rust,       opacity: 0.18 },
21	    { cx: '10%', cy: '70%', size: 600, color: BRAND.amber,      opacity: 0.15 },
22	    { cx: '60%', cy: '85%', size: 500, color: BRAND.rustBright, opacity: 0.12 },
23	    { cx: '40%', cy: '10%', size: 400, color: BRAND.sage,       opacity: 0.10 },
24	  ],
25	  soft: [
26	    { cx: '90%', cy: '20%', size: 500, color: BRAND.rust,  opacity: 0.10 },
27	    { cx: '15%', cy: '85%', size: 450, color: BRAND.amber, opacity: 0.10 },
28	    { cx: '50%', cy: '50%', size: 400, color: BRAND.sage,  opacity: 0.08 },
29	  ],
30	  cta: [
31	    { cx: '50%', cy: '0%',  size: 800, color: BRAND.rust,       opacity: 0.35 },
32	    { cx: '15%', cy: '90%', size: 600, color: BRAND.rustBright, opacity: 0.25 },
33	    { cx: '85%', cy: '90%', size: 600, color: BRAND.amber,      opacity: 0.20 },
34	  ],
35	};
36	
37	export function MangomintBlobs({ variant = 'soft' }: MangomintBlobsProps) {
38	  const blobs = blobVariants[variant];
39	  return (
40	    <div aria-hidden="true" style={{
41	      position: 'absolute', inset: 0, pointerEvents: 'none',
42	      mixBlendMode: variant === 'cta' ? 'screen' : 'multiply',
43	      overflow: 'hidden',
44	    } as React.CSSProperties}>
45	      {blobs.map((b, i) => (
46	        <div key={i} style={{
47	          position: 'absolute',
48	          left: b.cx, top: b.cy,
49	          width: b.size, height: b.size,
50	          transform: 'translate(-50%, -50%)',
51	          background: `radial-gradient(circle, ${b.color} 0%, transparent 70%)`,
52	          opacity: b.opacity,
53	          filter: 'blur(40px)',
54	          borderRadius: '50%',
55	        } as React.CSSProperties} />
56	      ))}
57	    </div>
58	  );
59	}
