"use client";

import React from "react";
import { BRAND, FONT, SHADOW } from "@/lib/brand";

interface DashboardMockupProps {
  hero?: boolean;
}

const appointments = [
  { time: "09:00", client: "Asha M.", service: "Koi Sleeve S3", duration: "3h", color: BRAND.rust },
  { time: "12:30", client: "Tomás R.", service: "Black-work chest", duration: "2h", color: BRAND.amber },
  { time: "15:00", client: "Nina K.", service: "Floral forearm", duration: "1.5h", color: BRAND.sage },
];

const stats = [
  { label: "Today's revenue", value: "$1,240", sub: "+12% vs last Fri" },
  { label: "Active projects", value: "14", sub: "3 closing this week" },
  { label: "Open deposits", value: "$4,320", sub: "8 clients" },
];

export function DashboardMockup({ hero = false }: DashboardMockupProps) {
  const scale = hero ? 1 : 0.92;

  return (
    <div
      style={{
        width: "100%",
        maxWidth: hero ? 880 : 760,
        margin: "0 auto",
        transform: `scale(${scale})`,
        transformOrigin: "top center",
        borderRadius: 20,
        overflow: "hidden",
        boxShadow: SHADOW.hero,
        background: BRAND.smoke,
        border: `1px solid ${BRAND.borderInk}`,
        fontFamily: FONT.sans,
      } as React.CSSProperties}
    >
      {/* Title bar */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 8,
          padding: "12px 16px",
          background: BRAND.char,
          borderBottom: `1px solid ${BRAND.borderInk}`,
        } as React.CSSProperties}
      >
        <div style={{ display: "flex", gap: 6 } as React.CSSProperties}>
          {[BRAND.rust, BRAND.amber, BRAND.sage].map((c, i) => (
            <div
              key={i}
              style={{ width: 10, height: 10, borderRadius: "50%", background: c, opacity: 0.8 } as React.CSSProperties}
            />
          ))}
        </div>
        <div
          style={{
            flex: 1, height: 8, borderRadius: 4,
            background: "rgba(247,247,245,0.06)", marginLeft: 8,
          } as React.CSSProperties}
        />
        <div
          style={{
            fontSize: 11, color: BRAND.stoneLight, fontWeight: 500,
            letterSpacing: "0.02em",
          } as React.CSSProperties}
        >
          InkOS · Today
        </div>
      </div>

      <div style={{ display: "flex", height: hero ? 440 : 380 } as React.CSSProperties}>
        {/* Sidebar */}
        <div
          style={{
            width: 56, background: BRAND.coal,
            borderRight: `1px solid ${BRAND.borderInk}`,
            display: "flex", flexDirection: "column",
            alignItems: "center", paddingTop: 16, gap: 6,
          } as React.CSSProperties}
        >
          {[BRAND.rust, BRAND.amber, BRAND.sage, BRAND.stoneLight, BRAND.stoneLight, BRAND.stoneLight].map((c, i) => (
            <div
              key={i}
              style={{
                width: 32, height: 32, borderRadius: 9,
                background: i === 0 ? BRAND.rust : "rgba(247,247,245,0.05)",
                opacity: i === 0 ? 1 : 0.6,
              } as React.CSSProperties}
            />
          ))}
        </div>

        {/* Main content */}
        <div style={{ flex: 1, padding: "20px 20px", overflow: "hidden" } as React.CSSProperties}>
          {/* Header */}
          <div style={{ marginBottom: 18 } as React.CSSProperties}>
            <div
              style={{
                fontSize: 11, fontWeight: 600, letterSpacing: "0.08em",
                color: BRAND.rust, textTransform: "uppercase", marginBottom: 4,
              } as React.CSSProperties}
            >
              Tuesday, 24 April
            </div>
            <div
              style={{
                fontSize: 17, fontWeight: 600, color: BRAND.bone,
                letterSpacing: "-0.01em",
              } as React.CSSProperties}
            >
              Good morning, Sable & Sparrow
            </div>
          </div>

          {/* Stats row */}
          <div
            style={{
              display: "grid", gridTemplateColumns: "1fr 1fr 1fr",
              gap: 10, marginBottom: 18,
            } as React.CSSProperties}
          >
            {stats.map((s, i) => (
              <div
                key={i}
                style={{
                  background: "rgba(247,247,245,0.04)",
                  border: `1px solid ${BRAND.borderInk}`,
                  borderRadius: 10, padding: "10px 12px",
                } as React.CSSProperties}
              >
                <div
                  style={{
                    fontSize: 10, color: BRAND.stoneLight,
                    fontWeight: 500, marginBottom: 4, letterSpacing: "0.01em",
                  } as React.CSSProperties}
                >
                  {s.label}
                </div>
                <div
                  style={{
                    fontSize: 18, fontWeight: 700, color: BRAND.bone,
                    letterSpacing: "-0.02em", marginBottom: 2,
                  } as React.CSSProperties}
                >
                  {s.value}
                </div>
                <div style={{ fontSize: 10, color: BRAND.sage } as React.CSSProperties}>
                  {s.sub}
                </div>
              </div>
            ))}
          </div>

          {/* Appointments */}
          <div
            style={{
              fontSize: 10, fontWeight: 600, color: BRAND.stoneLight,
              letterSpacing: "0.07em", textTransform: "uppercase",
              marginBottom: 8,
            } as React.CSSProperties}
          >
            Today&apos;s Chair
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 6 } as React.CSSProperties}>
            {appointments.map((a, i) => (
              <div
                key={i}
                style={{
                  display: "flex", alignItems: "center", gap: 10,
                  background: "rgba(247,247,245,0.03)",
                  border: `1px solid ${BRAND.borderInk}`,
                  borderLeft: `3px solid ${a.color}`,
                  borderRadius: 8, padding: "8px 12px",
                } as React.CSSProperties}
              >
                <div
                  style={{
                    fontFamily: FONT.mono, fontSize: 10,
                    color: BRAND.stoneLight, minWidth: 36,
                  } as React.CSSProperties}
                >
                  {a.time}
                </div>
                <div style={{ flex: 1 } as React.CSSProperties}>
                  <div style={{ fontSize: 12, fontWeight: 600, color: BRAND.bone } as React.CSSProperties}>
                    {a.client}
                  </div>
                  <div style={{ fontSize: 10, color: BRAND.stoneLight } as React.CSSProperties}>
                    {a.service}
                  </div>
                </div>
                <div
                  style={{
                    fontSize: 10, color: a.color,
                    fontFamily: FONT.mono,
                  } as React.CSSProperties}
                >
                  {a.duration}
                </div>
              </div>
            ))}
          </div>

          {/* Allergy alert */}
          <div
            style={{
              marginTop: 12, padding: "8px 12px", borderRadius: 8,
              background: "rgba(200,53,31,0.08)",
              border: `1px solid rgba(200,53,31,0.20)`,
              display: "flex", alignItems: "center", gap: 8,
            } as React.CSSProperties}
          >
            <div
              style={{
                width: 6, height: 6, borderRadius: "50%",
                background: BRAND.rust, flexShrink: 0,
              } as React.CSSProperties}
            />
            <div style={{ fontSize: 11, color: BRAND.rustBright } as React.CSSProperties}>
              <strong>Asha M.</strong> · Red ink allergy · latex sensitivity · surfaced from client record
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React from "react";
import { motion } from "framer-motion";
import { ArrowRight, PlayCircle } from "lucide-react";
import { BRAND, FONT, SHADOW, GRADIENT, fadeUp, stagger } from "@/lib/brand";
import { MangomintBlobs } from "@/components/brand/mangomint-blobs";
import { TriCircleMarkV2 } from "@/components/brand/tri-circle-mark";
import { DashboardMockup } from "@/components/dashboard/dashboard-mockup";
import { SectionEyebrow } from "@/components/shared/section-eyebrow";

const trustStats = [
  { value: "1,200+", label: "artists on waitlist" },
  { value: "US · UK · CA · AU", label: "global" },
  { value: "EU REACH", label: "compliant ink registry" },
  { value: "14 days", label: "free white-glove migration" },
];

export function Hero() {
  return (
    <section
      style={{
        position: "relative",
        background: BRAND.bone,
        overflow: "hidden",
        paddingTop: 100,
        paddingBottom: 80,
      } as React.CSSProperties}
    >
      {/* Blobs */}
      <MangomintBlobs variant="hero" />

      {/* HeroBloom gradient overlay */}
      <div
        aria-hidden="true"
        style={{
          position: "absolute",
          inset: 0,
          background: GRADIENT.heroBloom,
          pointerEvents: "none",
        } as React.CSSProperties}
      />

      {/* Subtle grid texture */}
      <div
        aria-hidden="true"
        style={{
          position: "absolute",
          inset: 0,
          pointerEvents: "none",
          backgroundImage:
            "linear-gradient(rgba(15,15,15,0.04) 1px, transparent 1px), linear-gradient(90deg, rgba(15,15,15,0.04) 1px, transparent 1px)",
          backgroundSize: "48px 48px",
          WebkitMaskImage:
            "radial-gradient(ellipse 80% 80% at 50% 50%, black 40%, transparent 100%)",
          maskImage:
            "radial-gradient(ellipse 80% 80% at 50% 50%, black 40%, transparent 100%)",
        } as React.CSSProperties}
      />

      {/* Content */}
      <div
        style={{
          position: "relative",
          maxWidth: 1120,
          margin: "0 auto",
          padding: "0 24px",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          textAlign: "center",
        } as React.CSSProperties}
      >
        {/* Status pill */}
        <motion.div
          variants={fadeUp}
          initial="hidden"
          animate="visible"
          style={{
            display: "inline-flex",
            alignItems: "center",
            gap: 10,
            padding: "8px 16px",
            borderRadius: 100,
            background: BRAND.white,
            border: `1px solid ${BRAND.border}`,
            boxShadow: SHADOW.soft,
            marginBottom: 32,
            fontFamily: FONT.sans,
            fontSize: 13,
            fontWeight: 500,
            color: BRAND.stoneDark,
          } as React.CSSProperties}
        >
          <TriCircleMarkV2 size={20} />
          <span>The studio OS for tattoo &middot; v1 in private beta</span>
        </motion.div>

        {/* H1 */}
        <motion.h1
          variants={fadeUp}
          initial="hidden"
          animate="visible"
          style={{
            fontFamily: FONT.serif,
            fontSize: "clamp(48px, 7vw, 96px)",
            lineHeight: 1.02,
            letterSpacing: "-0.025em",
            color: BRAND.onyx,
            fontWeight: 400,
            marginBottom: 24,
            maxWidth: 900,
          } as React.CSSProperties}
        >
          The studio OS built like a{" "}
          <em
            style={{
              color: BRAND.rust,
              fontStyle: "italic",
              fontFamily: FONT.serif,
            } as React.CSSProperties}
          >
            tattoo
          </em>
          , not a spreadsheet.
        </motion.h1>

        {/* Subhead */}
        <motion.p
          variants={fadeUp}
          initial="hidden"
          animate="visible"
          style={{
            fontFamily: FONT.sans,
            fontSize: 18,
            lineHeight: 1.6,
            color: BRAND.stoneDark,
            maxWidth: 560,
            marginBottom: 40,
          } as React.CSSProperties}
        >
          Sessions linked into projects. Deposits pooled per sleeve. Allergies surfaced before the chair. One OS for every room in your studio.
        </motion.p>

        {/* CTAs */}
        <motion.div
          variants={fadeUp}
          initial="hidden"
          animate="visible"
          style={{
            display: "flex",
            alignItems: "center",
            gap: 12,
            flexWrap: "wrap",
            justifyContent: "center",
            marginBottom: 64,
          } as React.CSSProperties}
        >
          <button
            type="button"
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: 8,
              padding: "13px 26px",
              borderRadius: 100,
              background: BRAND.onyx,
              color: BRAND.bone,
              fontFamily: FONT.sans,
              fontSize: 15,
              fontWeight: 600,
              border: "none",
              cursor: "pointer",
              letterSpacing: "-0.005em",
              boxShadow: SHADOW.card,
            } as React.CSSProperties}
          >
            Start a 14-day trial
            <ArrowRight size={16} strokeWidth={2} />
          </button>

          <button
            type="button"
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: 8,
              padding: "13px 26px",
              borderRadius: 100,
              background: "transparent",
              color: BRAND.onyx,
              fontFamily: FONT.sans,
              fontSize: 15,
              fontWeight: 600,
              border: `1.5px solid ${BRAND.border}`,
              cursor: "pointer",
              letterSpacing: "-0.005em",
            } as React.CSSProperties}
          >
            <PlayCircle size={16} strokeWidth={1.8} />
            Watch a 90-second tour
          </button>
        </motion.div>

        {/* Dashboard mockup */}
        <motion.div
          variants={fadeUp}
          initial="hidden"
          animate="visible"
          style={{
            position: "relative",
            width: "100%",
            marginBottom: 64,
          } as React.CSSProperties}
        >
          {/* Decorative blob behind mockup */}
          <div
            aria-hidden="true"
            style={{
              position: "absolute",
              top: "50%",
              left: "50%",
              transform: "translate(-50%, -50%)",
              width: 600,
              height: 400,
              background: `radial-gradient(ellipse, ${BRAND.rustWash} 0%, transparent 70%)`,
              filter: "blur(60px)",
