// ── Koi SVG ─────────────────────────────────────────────────────────────────

interface KoiSvgProps {
  stage: Stage;
  isRef: boolean;
  isHeal: boolean;
  isHealed: boolean;
}

function KoiSvg({ stage, isRef, isHeal, isHealed }: KoiSvgProps) {
  const strokeW = isRef ? 1.2 : 2;
  const finStrokeW = isRef ? 1.0 : 1.6;
  const opacity = isRef ? 0.5 : 1;

  return (
    <svg
      width="80"
      height="120"
      viewBox="0 0 80 120"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      style={{ opacity } as React.CSSProperties}
      aria-hidden="true"
    >
      {/* Body ellipse */}
      <ellipse
        cx="40"
        cy="64"
        rx="22"
        ry="38"
        stroke={stage.lineColor}
        strokeWidth={strokeW}
        fill={isRef ? "none" : stage.lineColor}
        fillOpacity={isRef ? 0 : 0.12}
      />
      {/* Tail flick */}
      <path
        d="M 28 26 Q 40 8 52 26"
        stroke={stage.lineColor}
        strokeWidth={strokeW}
        fill="none"
        strokeLinecap="round"
      />
      {/* Top fin */}
      <path
        d="M 40 28 Q 54 40 50 58"
        stroke={stage.lineColor}
        strokeWidth={finStrokeW}
        fill="none"
        strokeLinecap="round"
      />
      {/* Eye */}
      <circle cx="36" cy="55" r={isRef ? 2 : 2.5} fill={stage.lineColor} />

      {/* HEAL stage: scab dots */}
      {isHeal && (
        <>
          <circle cx="38" cy="62" r="2.5" fill={BRAND.amber} opacity="0.6" />
          <circle cx="44" cy="72" r="2" fill={BRAND.amber} opacity="0.5" />
          <circle cx="36" cy="76" r="1.8" fill={BRAND.amber} opacity="0.45" />
          <circle cx="42" cy="82" r="2" fill={BRAND.amber} opacity="0.5" />
        </>
      )}

      {/* HEALED stage: whiskers */}
      {isHealed && (
        <>
          <line x1="22" y1="58" x2="36" y2="60" stroke={BRAND.sage} strokeWidth="1.2" strokeLinecap="round" />
          <line x1="22" y1="63" x2="36" y2="63" stroke={BRAND.sage} strokeWidth="1.2" strokeLinecap="round" />
          <line x1="44" y1="60" x2="58" y2="58" stroke={BRAND.sage} strokeWidth="1.2" strokeLinecap="round" />
          <line x1="44" y1="63" x2="58" y2="63" stroke={BRAND.sage} strokeWidth="1.2" strokeLinecap="round" />
        </>
      )}
    </svg>
  );
}

