        position: "relative",
        borderRadius: 18,
        overflow: "visible",
        display: "flex",
        flexDirection: "column",
      } as React.CSSProperties}
    >
      {/* Featured badge */}
      {tier.featured && tier.featuredLabel && (
        <div
          style={{
            position: "absolute",
            top: -10,
            left: "50%",
            transform: "translateX(-50%)",
            padding: "4px 14px",
            borderRadius: 100,
            background: `linear-gradient(135deg, ${BRAND.rust} 0%, ${BRAND.rustBright} 100%)`,
            fontFamily: FONT.sans,
            fontSize: 11,
            fontWeight: 700,
            color: BRAND.bone,
            letterSpacing: "0.02em",
            whiteSpace: "nowrap",
            zIndex: 10,
          } as React.CSSProperties}
        >
          {tier.featuredLabel}
        </div>
      )}

      <div
        style={{
          flex: 1,
          background: tier.featured
            ? BRAND.smoke
            : "rgba(247,247,245,0.03)",
          border: tier.featured
            ? `1.5px solid ${BRAND.rustBright}`
            : `1px solid ${BRAND.borderInk}`,
          borderRadius: 18,
          padding: "28px 24px",
          display: "flex",
          flexDirection: "column",
          boxShadow: tier.featured
            ? `0 0 0 1px rgba(200,53,31,0.20), 0 20px 48px -12px rgba(200,53,31,0.30)`
