        } as React.CSSProperties}
      >
        {/* Tier name + desc */}
        <div style={{ marginBottom: 20 } as React.CSSProperties}>
          <div
            style={{
              fontFamily: FONT.sans,
              fontSize: 16,
              fontWeight: 700,
              color: BRAND.bone,
              letterSpacing: "-0.01em",
              marginBottom: 4,
