          >
            {tier.name}
          </div>
          <div
            style={{
              fontFamily: FONT.sans,
              fontSize: 13,
              color: BRAND.stoneLight,
              lineHeight: 1.4,
            } as React.CSSProperties}
          >
            {tier.desc}
          </div>
        </div>

        {/* Price */}
        <div
          style={{
            display: "flex",
            alignItems: "baseline",
            gap: 4,
            marginBottom: 24,
          } as React.CSSProperties}
        >
          <span
            style={{
              fontFamily: FONT.sans,
              fontSize: 48,
              fontWeight: 700,
              color: BRAND.bone,
              letterSpacing: "-0.03em",
              lineHeight: 1,
            } as React.CSSProperties}
          >
            {tier.price}
          </span>
          <span
            style={{
              fontFamily: FONT.sans,
              fontSize: 13,
              color: BRAND.stoneLight,
            } as React.CSSProperties}
          >
            {tier.period}
          </span>
        </div>

        {/* CTA */}
        <button
          type="button"
          style={{
            display: "inline-flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 8,
            padding: "11px 20px",
            borderRadius: 100,
            background: tier.featured ? BRAND.bone : "transparent",
            color: tier.featured ? BRAND.onyx : BRAND.bone,
            fontFamily: FONT.sans,
            fontSize: 14,
            fontWeight: 600,
            border: tier.featured ? "none" : `1.5px solid ${BRAND.borderInk}`,
            cursor: "pointer",
            letterSpacing: "-0.005em",
            marginBottom: 24,
            width: "100%",
          } as React.CSSProperties}
        >
          {tier.cta}
          <ArrowRight size={14} strokeWidth={2} />
        </button>

        {/* Divider */}
        <div
          aria-hidden="true"
          style={{
            height: 1,
            background: BRAND.borderInk,
            marginBottom: 20,
          } as React.CSSProperties}
        />

        {/* Feature lines */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 10,
            flex: 1,
          } as React.CSSProperties}
        >
          {tier.lines.map((line, i) => {
            const isContinuation = line.startsWith("Everything in");
            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "flex-start",
                  gap: 10,
                } as React.CSSProperties}
              >
                {isContinuation ? (
                  <span
                    style={{
                      fontFamily: FONT.mono,
                      fontSize: 12,
                      color: BRAND.bone,
                      flexShrink: 0,
                      marginTop: 1,
                    } as React.CSSProperties}
                  >
                    ↳
                  </span>
                ) : (
                  <Check
                    size={14}
                    color={BRAND.sage}
                    strokeWidth={2.2}
                    style={{ flexShrink: 0, marginTop: 2 } as React.CSSProperties}
                  />
                )}
                <span
                  style={{
                    fontFamily: FONT.sans,
                    fontSize: 13,
                    color: isContinuation ? BRAND.bone : BRAND.stoneLight,
                    fontWeight: isContinuation ? 600 : 400,
                    lineHeight: 1.4,
                  } as React.CSSProperties}
                >
                  {line}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    </motion.div>
  );
}

